class Solution:
    def maxAreaOfIsland(self, grid: List[List[int]]) -> int:
        directions = [[-1,  0], [ 1,  0], [ 0,  1], [ 0, -1]]

        def dfs(i, j, grid, area):
            if not (0 <= i < len(grid) and \
                    0 <= j < len(grid[0]) and \
                    grid[i][j] > 0):
                return False
            grid[i][j] *= -1
            area[0] += 1
            for d in directions:
                dfs(i+d[0], j+d[1], grid, area)
            return True

        result = 0
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                area = [0]
                if dfs(i, j, grid, area):
                    result = max(result, area[0])
        return result

class Solution:
    def countBinarySubstrings(self, s: str) -> int:
        result, prev, curr = 0, 0, 1
        for i in range(1, len(s)):
            if s[i-1] != s[i]:
                result += min(prev, curr)
                prev, curr = curr, 1
            else:
                curr += 1
        result += min(prev, curr)
        return result

class Solution:
    def findShortestSubArray(self, nums):
        # Group indexes by element type
        d = defaultdict(list)
        for i,x in enumerate(nums):
            d[x].append(i)
        #
        # Find highest Degree
        m = max([ len(v) for v in d.values() ])
        #
        # Find shortest span for max. degree
        best = len(nums)
        for v in d.values():
            if len(v)==m:
                best = min(best,v[-1]-v[0]+1)
        return best
